func:
// 계측값 블록(PLC 입력 레지스터 0..27 = 값 12점 + 스캔 순번 + 설비 시각, 한 번의 FC4 읽기).
// 새 스캔일 때만 UNS 와 수업용 edgex/telemetry 로 낸다. 결측 표시값은 버리고 품질 BAD 로 낸다.
const reg = global.get('registry');
const w = msg.payload;
if (!Array.isArray(w) || w.length < 28) return null;
const seq = w[24] * 65536 + w[25];
const pts = w[26] * 65536 + w[27];
if (seq === context.get('lastSeq')) return null;
context.set('lastSeq', seq);
const st = flow.get('plcStatus') || {};
const fieldOk = st.field_comm === 1;
const tsNs = Date.now() * 1e6;
const buf = Buffer.alloc(4);
const f32 = (hi, lo) => { buf.writeUInt16BE(hi, 0); buf.writeUInt16BE(lo, 2); return buf.readFloatBE(0); };
const lastPub = flow.get('lastPub') || {};
const uns = [];
const readings = [];
for (const t of reg.tags) {
    const raw = f32(w[t.plc_ir], w[t.plc_ir + 1]);
    const value = Number.isFinite(raw) && raw > -1000 ? Math.round(raw * 10000) / 10000 : null;
    const quality = value === null ? 'BAD' : (fieldOk ? 'GOOD' : 'STALE');
    const lp = lastPub[t.tag];
    // 보고 조건(17번 D2): 품질 변화, deadband 를 넘는 변화, 최대 간격(공정 시간 — 설비 시각 pts 로 잰다)
    const due = !lp || lp.quality !== quality || value === null || lp.value === null
        || Math.abs(value - lp.value) >= t.deadband || pts < lp.pts || (pts - lp.pts) >= t.max_interval_s;
    if (due) {
        uns.push({ topic: t.topic, qos: 1, retain: false, payload: JSON.stringify({ ts: tsNs, value, quality, seq, pts }) });
        lastPub[t.tag] = { value, quality, pts };
    }
    if (value !== null) {
        readings.push({ id: `${seq}-${t.tag}`, origin: tsNs, deviceName: reg.hierarchy.line, resourceName: t.tag,
            profileName: 'AR100-Reactor-Line', valueType: 'Float32', value: String(value) });
    }
}
flow.set('lastPub', lastPub);
flow.set('lastValues', { seq, pts, tsNs });
// 수업 자료가 쓰는 edgex/telemetry: 같은 데이터를 EdgeX Event 모양으로 낸다(같은 데이터의 이름 둘, 정본은 등록부)
uns.push({ topic: reg.edgex_telemetry_topic, qos: 1, retain: false, payload: JSON.stringify({
    apiVersion: 'v3', id: String(seq), deviceName: reg.hierarchy.line, profileName: 'AR100-Reactor-Line',
    sourceName: 'AllSensors', origin: tsNs, readings }) });
return { batch: uns };

// 상태 블록(PLC 홀딩 레지스터 100..118 = 설정값 3 + 상태·ACK 16, 한 번의 FC3 읽기).
// 바뀐 상태만 보존(retain) 토픽으로 내고, 최대 간격마다 전부 다시 낸다. ACK 순번이 바뀌면 ACK 를 낸다.
const reg = global.get('registry');
const w = msg.payload;
if (!Array.isArray(w) || w.length < 19) return null;
const s = {};
reg.plc.read_status.fields.forEach((k, i) => { s[k] = w[i]; });
const prev = flow.get('plcStatus');
flow.set('plcStatus', s);
const now = Date.now();
const tsNs = now * 1e6;
// RUN/STOP: PLC 하트비트가 2초 넘게 멈추면 STOP(PLC 가 프로그램을 돌리지 않음)
let hb = context.get('hb') || { v: -1, at: now };
if (s.heartbeat !== hb.v) hb = { v: s.heartbeat, at: now };
context.set('hb', hb);
const P = `${reg.line_prefix}/${reg.plc.asset}`;
const values = {
    [`${P}/status/mode`]: reg.plc.modes[String(s.mode)] || 'UNKNOWN',
    [`${P}/status/maintenance`]: s.maintenance === 1,
    [`${P}/status/maint_operator`]: s.maint_operator,
    [`${P}/status/interlock`]: s.interlock === 1,
    [`${P}/status/estop`]: s.estop === 1,
    [`${P}/status/field_comm`]: s.field_comm === 1,
    [`${P}/status/run_state`]: (now - hb.at) > 2000 ? 'STOP' : 'RUN',
    [`${P}/status/fb_fault`]: s.fb_fault,
};
const sp = { 'P-101/speed_sp': s.sp_pump, 'CV-101/open_sp': s.sp_valve, 'R-101/temp_sp': s.sp_temp_x10 };
for (const c of reg.commands) {
    const key = `${c.asset}/${c.name}`;
    if (key in reg.plc.outputs_bits) values[c.status_topic] = ((s.outputs >> reg.plc.outputs_bits[key]) & 1) === 1;
    else if (key in sp) values[c.status_topic] = sp[key] / (c.scale || 1);
}
const last = context.get('last') || {};
const full = (now - (context.get('fullAt') || 0)) >= reg.plc.state_max_interval_wall_s * 1000;
if (full) context.set('fullAt', now);
const out = [];
for (const [topic, value] of Object.entries(values)) {
    if (full || last[topic] !== value) {
        out.push({ topic, qos: 1, retain: true, payload: JSON.stringify({ ts: tsNs, value, quality: 'GOOD' }) });
        last[topic] = value;
    }
}
context.set('last', last);
// ACK: 기동 뒤 첫 읽기에서는 내지 않는다(이전 ACK 를 새 것으로 오인하지 않게). 순번은 PLC 에서 이어받아 다음 명령 순번이 겹치지 않게 한다.
if (!prev) {
    flow.set('opSeq', s.op_ack_seq);
    flow.set('rqSeq', s.rq_ack_seq);
} else {
    const codes = reg.plc.ack_codes;
    if (s.op_ack_seq !== prev.op_ack_seq) {
        const cmd = (flow.get('opBySeq') || {})[s.op_ack_seq] || null;
        out.push({ topic: reg.plc.ack_operator_topic, qos: 1, retain: false, payload: JSON.stringify({
            ts: tsNs, source: 'plc', seq: s.op_ack_seq, code: s.op_ack_code, result: codes[String(s.op_ack_code)] || 'UNKNOWN', command: cmd }) });
    }
    if (s.rq_ack_seq !== prev.rq_ack_seq) {
        const hash = s.rq_ack_hash_hi * 65536 + s.rq_ack_hash_lo;
        const job = (flow.get('jobByHash') || {})[hash] || null;
        out.push({ topic: reg.plc.ack_request_topic, qos: 1, retain: false, payload: JSON.stringify({
            ts: tsNs, source: 'plc', seq: s.rq_ack_seq, job_hash: hash, job_order_id: job,
            code: s.rq_ack_code, result: codes[String(s.rq_ack_code)] || 'UNKNOWN' }) });
    }
}
if (!out.length) return null;
return { batch: out };

// 장치 통신 상태(Sparkplug DDEATH 흉내): PLC 폴링 성공·실패로 PLC 통신 상태를 내고,
// 끊기면 마지막 값을 품질 STALE 로 한 번 낸다. 입력 = Modbus 읽기 노드들의 상태(status 노드).
const reg = global.get('registry');
const st = msg.status || {};
const text = String(st.text || '').toLowerCase();
let online = null;
if (/error|disconnect|closed|fail|timeout|broken|reconnect|stopped/.test(text) || st.fill === 'red') online = false;
else if (/active|polling|reading done|connected/.test(text) || st.fill === 'green') online = true;
if (online === null || online === flow.get('plcOnline')) return null;
flow.set('plcOnline', online);
node.status({ fill: online ? 'green' : 'red', shape: 'dot', text: online ? 'PLC 통신 정상' : 'PLC 통신 끊김' });
const tsNs = Date.now() * 1e6;
const out = [{ topic: reg.plc.comm_topic, qos: 1, retain: true, payload: JSON.stringify({ ts: tsNs, value: online, quality: 'GOOD' }) }];
if (!online) {
    const lastPub = flow.get('lastPub') || {};
    const lv = flow.get('lastValues') || {};
    for (const t of reg.tags) {
        const lp = lastPub[t.tag];
        if (!lp) continue;
        out.push({ topic: t.topic, qos: 1, retain: false, payload: JSON.stringify({ ts: tsNs, value: lp.value, quality: 'STALE', seq: lv.seq, pts: lv.pts }) });
        lastPub[t.tag] = { ...lp, quality: 'STALE' };
    }
    flow.set('lastPub', lastPub);
}
return { batch: out };

// 끊김 시 저장 후 전송(store-and-forward): OT 허브 연결이 끊긴 동안 보낼 메시지를 디스크 컨텍스트에 쌓고,
// 다시 붙으면 순서대로 먼저 보낸다. 한도를 넘으면 새 값을 버리고 버린 건수를 센다(17번 D10 과 같은 정책).
// 입력: {batch:[메시지…]} 또는 {_flush:true}(재연결 알림). 출력: MQTT 출력 노드로 보낼 메시지들.
const LIMIT = 72000;
const up = flow.get('mqttUp') === true;
const q = flow.get('safQueue', 'disk') || [];
const incoming = msg._flush ? [] : (Array.isArray(msg.batch) ? msg.batch : [msg]);
const pack = m => ({ topic: m.topic, payload: m.payload, qos: m.qos, retain: m.retain });
if (!up) {
    for (const m of incoming) {
        if (q.length >= LIMIT) { flow.set('safDropped', (flow.get('safDropped') || 0) + 1); continue; }
        q.push(pack(m));
    }
    flow.set('safQueue', q, 'disk');
    node.status({ fill: 'yellow', shape: 'ring', text: `끊김: 보관 ${q.length}` });
    return null;
}
const out = q.concat(incoming.map(pack));
if (q.length) {
    flow.set('safQueue', [], 'disk');
    node.status({ fill: 'green', shape: 'dot', text: `재전송 ${q.length}` });
}
flow.set('published', (flow.get('published') || 0) + out.length);
return [out];

// OT 허브 연결 상태(MQTT 출력 노드의 상태) → 끊김 버퍼가 쓰는 연결 표시. 다시 붙으면 쌓인 것을 바로 보낸다.
const text = String((msg.status || {}).text || '').toLowerCase();
const up = text.includes('connected') && !text.includes('disconnected') && !text.includes('connecting');
const was = flow.get('mqttUp') === true;
flow.set('mqttUp', up);
if (up && !was) return { _flush: true };
return null;

// 시각 동기: 1초마다 PLC %MW0..1 에 epoch 초를 쓴다(PLC 가 외부 요청 만료를 검사하는 기준).
const reg = global.get('registry');
const t = Math.floor(Date.now() / 1000);
msg.payload = { value: [Math.floor(t / 65536), t % 65536], fc: 16, unitid: reg.plc.unit_id, address: reg.plc.write.time_sync, quantity: 2 };
return msg;

// 운전원 명령(FUXA → …/cmd/operator) → PLC 운전원 채널(%MW10..12). 받을지는 PLC 가 정하고 ACK 로 답한다.
// 엣지는 모양만 거른다: 보존(retain) 메시지·5초 넘은 명령·모르는 명령은 쓰지 않고 거부 ACK 를 낸다.
// 출력 1 = PLC 쓰기(명령 코드·값 → 끝나면 순번), 출력 2 = 엣지 거부 ACK
const reg = global.get('registry');
const asset = msg.topic.split('/')[3];
const tsNs = Date.now() * 1e6;
const reject = (result, extra) => [null, { batch: [{ topic: reg.plc.ack_operator_topic, qos: 1, retain: false,
    payload: JSON.stringify({ ts: tsNs, source: 'edge', result, command: { topic: msg.topic, ...extra } }) }] }];
let body;
try { body = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { return reject('BAD_PAYLOAD', {}); }
const cmd = reg.commands.find(c => c.asset === asset && c.name === body.command);
if (!cmd) return reject('UNKNOWN_COMMAND', { command: body.command });
if (msg.retain) return reject('RETAINED_COMMAND', { command: body.command });
const age = (Date.now() - Date.parse(body.ts)) / 1000;
if (!Number.isFinite(age) || age > 5 || age < -5) return reject('STALE_COMMAND', { command: body.command, ts: body.ts });
let v;
if (cmd.kind === 'switch') v = [true, 1, '1', 'true', 'on', 'ON'].includes(body.value) ? 1 : 0;
else if (cmd.kind === 'setpoint') v = Math.round(Number(body.value) * (cmd.scale || 1));
else if (cmd.kind === 'mode') v = ({ REMOTE_MANUAL: 1, REMOTE_AUTO: 2 })[body.value] || Number(body.value);
else if (cmd.kind === 'reset') v = 1;
else v = Number(body.value);
if (!Number.isInteger(v)) return reject('BAD_VALUE', { command: body.command, value: body.value });
const seq = (((flow.get('opSeq') || 0) + 1) & 0xFFFF) || 1;
flow.set('opSeq', seq);
const bySeq = flow.get('opBySeq') || {};
bySeq[seq] = { topic: msg.topic, command: body.command, value: body.value, ts: body.ts };
for (const k of Object.keys(bySeq).slice(0, -64)) delete bySeq[k];
flow.set('opBySeq', bySeq);
const base = reg.plc.write.operator;
// 명령 코드·값을 먼저 쓰고, 그 쓰기가 끝나면 순번을 쓴다(PLC 는 순번이 바뀐 것을 새 명령으로 본다)
return [{ payload: { value: [cmd.code, v & 0xFFFF], fc: 16, unitid: reg.plc.unit_id, address: base + 1, quantity: 2 },
          seqWrite: { value: [seq], fc: 16, unitid: reg.plc.unit_id, address: base, quantity: 1 } }, null];

// 앞의 쓰기(명령 코드·값)가 끝났으니 순번을 쓴다.
if (!msg.seqWrite) return null;
return { payload: msg.seqWrite };

// 외부 요청 명령(OT 수신기 → …/cmd/request) → PLC 외부 요청 채널(%MW20..27). PLC 가 만료·중복·모드·범위를 다시 검사한다.
const reg = global.get('registry');
let b;
try { b = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { node.warn('요청 명령 해석 실패'); return null; }
if (msg.retain) return null;
const ok = typeof b.job_order_id === 'string' && Number.isInteger(b.code) && Number.isInteger(b.value)
    && Number.isInteger(b.expires_at) && Number.isInteger(b.job_hash) && b.job_hash > 0;
if (!ok) { node.warn('요청 명령 형식 오류'); return null; }
const seq = (((flow.get('rqSeq') || 0) + 1) & 0xFFFF) || 1;
flow.set('rqSeq', seq);
const byHash = flow.get('jobByHash') || {};
byHash[b.job_hash] = b.job_order_id;
for (const k of Object.keys(byHash).slice(0, -64)) delete byHash[k];
flow.set('jobByHash', byHash);
const base = reg.plc.write.request;
const e = b.expires_at >>> 0;
return { payload: { value: [b.code, b.value & 0xFFFF, e >>> 16, e & 0xFFFF, b.operator_accepted ? 1 : 0,
                            b.job_hash >>> 16, b.job_hash & 0xFFFF], fc: 16, unitid: reg.plc.unit_id, address: base + 1, quantity: 7 },
         seqWrite: { value: [seq], fc: 16, unitid: reg.plc.unit_id, address: base, quantity: 1 } };

// 앞의 쓰기(명령 코드·값)가 끝났으니 순번을 쓴다.
if (!msg.seqWrite) return null;
return { payload: msg.seqWrite };

// 엣지 지표(Prometheus 텍스트). OT 쪽 Prometheus agent 가 읽는다.
const q = flow.get('safQueue', 'disk') || [];
msg.payload = [
    '# HELP edge_published_total UNS 로 낸 메시지 수', '# TYPE edge_published_total counter', `edge_published_total ${flow.get('published') || 0}`,
    '# HELP edge_saf_queue 끊김 버퍼에 쌓인 메시지 수', '# TYPE edge_saf_queue gauge', `edge_saf_queue ${q.length}`,
    '# HELP edge_saf_dropped_total 끊김 버퍼 한도로 버린 메시지 수', '# TYPE edge_saf_dropped_total counter', `edge_saf_dropped_total ${flow.get('safDropped') || 0}`,
    '# HELP edge_plc_online PLC 통신 정상(1)', '# TYPE edge_plc_online gauge', `edge_plc_online ${flow.get('plcOnline') === false ? 0 : 1}`,
    '# HELP edge_mqtt_up OT 허브 연결(1)', '# TYPE edge_mqtt_up gauge', `edge_mqtt_up ${flow.get('mqttUp') === true ? 1 : 0}`,
    ''].join('\n');
msg.headers = { 'Content-Type': 'text/plain; version=0.0.4' };
return msg;

// OT 작업 요청 수신기(현업 L3 MES 서버·SCADA MES 모듈 흉내, 17번 E20): 받을지 OT 안에서 정한다.
// 입력 = 스키마 검사를 통과한 작업 요청. 검사: 중복(QoS 1)·허용 작업·설비·파라미터 범위·만료·모드·정비 모드.
// REMOTE_AUTO → 자동 수용(StoreAndStart), REMOTE_MANUAL → 운전원 대기로 저장(Store), 그 밖 → 거부.
// 결정과 제어기 명령 토픽 발행까지만 한다(설비 쓰기는 엣지 → PLC 길).
const reg = global.get('registry');
const wm = global.get('workMastersOt');
const crypto = global.get('crypto');
const req = msg.payload;
const now = Date.now() / 1000;
const iso = new Date().toISOString();
const resp = (stage, status, reason) => ({ topic: `${reg.request.response_prefix}/${req.job_order_id}`, qos: 1, retain: false,
    payload: JSON.stringify({ job_order_id: req.job_order_id, stage, status, reason, ts: iso }) });
const pendingMsg = (pending) => {
    const items = Object.values(pending).sort((a, b) => a.received_at - b.received_at);
    const h = items[0];
    return { topic: reg.request.pending_topic, qos: 1, retain: true, payload: JSON.stringify({
        count: items.length, head_job: h ? h.job_order_id : '', head_wm: h ? h.work_master_id : '',
        head_desc: h ? h.desc : '대기 중인 요청 없음', head_context: h ? (h.context_summary || '') : '',
        head_wait_s: h ? Math.round(now - h.received_at) : 0,
        items: items.map(i => ({ job_order_id: i.job_order_id, work_master_id: i.work_master_id, desc: i.desc })) }) };
};
flow.set('requests', (flow.get('requests') || 0) + 1);
// 중복: MQTT QoS 1 은 같은 메시지를 다시 보낼 수 있다(규격). 만료 시간 안에 본 ID 는 다시 처리하지 않는다(17번 E19)
const seen = flow.get('seen') || {};
for (const k of Object.keys(seen)) if (seen[k] < now) delete seen[k];
if (seen[req.job_order_id]) { flow.set('seen', seen); return null; }
seen[req.job_order_id] = (Number(req.expires_at) || now) + 60;
flow.set('seen', seen);
const reject = (reason) => { flow.set('rejected', (flow.get('rejected') || 0) + 1); return { batch: [resp('receipt', 'REJECTED', reason)] }; };
const w = wm.find(x => x.work_master_id === req.work_master_id);
if (!w) return reject('NOT_ALLOWED');
if (w.equipment_id !== req.equipment_id) return reject('EQUIPMENT_MISMATCH');
let value = w.fixed_value;
for (const p of w.parameters) {
    const got = (req.job_order_parameters || []).find(x => x.id === p.id);
    if (!got) return reject('PARAMETER_MISSING');
    if (!(got.value >= p.min && got.value <= p.max)) return reject('PARAMETER_RANGE');
    value = Math.round(got.value * (w.scale || 1));
}
if (!(Number(req.expires_at) > now)) return reject('EXPIRED');
const plc = flow.get('plc') || {};
if (plc.run_state !== 'RUN' || plc.field_comm === false) return reject('PLC_UNAVAILABLE');
if (plc.mode === 'LOCAL') return reject('LOCAL_MODE');
if (plc.maintenance === true) return reject('MAINTENANCE');
const hash = parseInt(crypto.createHash('sha256').update(req.job_order_id).digest('hex').slice(0, 8), 16) || 1;
const job = { job_order_id: req.job_order_id, work_master_id: w.work_master_id, equipment_id: w.equipment_id, desc: w.desc,
    code: w.code, value, command_topic: w.command_topic, job_hash: hash, received_at: now, expires_at: Math.floor(Number(req.expires_at)),
    context_summary: req.context ? String(req.context.summary || '').slice(0, 120) : '' };
if (plc.mode === 'REMOTE_AUTO') {
    const cmd = { topic: w.command_topic, qos: 1, retain: false, payload: JSON.stringify({ job_order_id: job.job_order_id,
        code: job.code, value: job.value, expires_at: job.expires_at, operator_accepted: 0, job_hash: hash }) };
    return { batch: [resp('receipt', 'AUTO_ACCEPTED', 'REMOTE_AUTO'), cmd] };
}
if (plc.mode === 'REMOTE_MANUAL') {
    const pending = flow.get('pending') || {};
    pending[job.job_order_id] = job;
    flow.set('pending', pending);
    return { batch: [resp('receipt', 'OPERATOR_WAIT', 'STORED'), pendingMsg(pending)] };
}
return reject('MODE_UNKNOWN');

// 스키마 검사를 통과하지 못한 요청: 요청 ID 를 알 수 있으면 거부 응답을 낸다(알 수 없으면 기록만).
const reg = global.get('registry');
let id = null;
try { id = JSON.parse(msg.payload).job_order_id; } catch (e) { /* 해석 불가 */ }
if (typeof msg.payload === 'object' && msg.payload) id = msg.payload.job_order_id;
flow.set('rejected', (flow.get('rejected') || 0) + 1);
if (typeof id !== 'string' || !/^[A-Za-z0-9._:-]{8,80}$/.test(id)) { node.warn('스키마 오류 요청(ID 없음) 버림'); return null; }
return { batch: [{ topic: `${reg.request.response_prefix}/${id}`, qos: 1, retain: false,
    payload: JSON.stringify({ job_order_id: id, stage: 'receipt', status: 'REJECTED', reason: 'SCHEMA_INVALID',
        detail: JSON.stringify(msg.schemaError || (msg.error && msg.error.message) || '').slice(0, 300), ts: new Date().toISOString() }) }] };

// PLC 상태 토픽(모드·정비 모드·실행 상태·현장 통신)을 수신기가 따로 구독해 둔다(엣지 수집 흐름과 떨어진 전용 계정).
const field = msg.topic.split('/').pop();
let v;
try { v = JSON.parse(msg.payload).value; } catch (e) { return null; }
const plc = flow.get('plc') || {};
plc[field] = v;
flow.set('plc', plc);
return null;

// 운전원 결정(FUXA "받은 요청" 화면 → …/request/decision): 수락이면 새 만료(발행 + 30 s)와 운전원 수락 표시를 붙여
// 제어기 명령 토픽으로 낸다(Store 후 운전원 Start). 거부면 거부 응답. 10초 넘은 결정·없는 요청은 무시한다.
const reg = global.get('registry');
let d;
try { d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { return null; }
if (msg.retain) return null;
const age = (Date.now() - Date.parse(d.ts)) / 1000;
if (!Number.isFinite(age) || age > 10 || age < -10) { node.warn('오래된 운전원 결정 무시'); return null; }
const pending = flow.get('pending') || {};
const job = pending[d.job_order_id];
if (!job) { node.warn(`대기 목록에 없는 요청: ${d.job_order_id}`); return null; }
delete pending[d.job_order_id];
flow.set('pending', pending);
const now = Date.now() / 1000;
const iso = new Date().toISOString();
const resp = (status, reason) => ({ topic: `${reg.request.response_prefix}/${job.job_order_id}`, qos: 1, retain: false,
    payload: JSON.stringify({ job_order_id: job.job_order_id, stage: 'operator', status, reason, ts: iso }) });
const items = Object.values(pending).sort((a, b) => a.received_at - b.received_at);
const h = items[0];
const pendingMsg = { topic: reg.request.pending_topic, qos: 1, retain: true, payload: JSON.stringify({
    count: items.length, head_job: h ? h.job_order_id : '', head_wm: h ? h.work_master_id : '',
    head_desc: h ? h.desc : '대기 중인 요청 없음', head_context: h ? (h.context_summary || '') : '',
    head_wait_s: h ? Math.round(now - h.received_at) : 0,
    items: items.map(i => ({ job_order_id: i.job_order_id, work_master_id: i.work_master_id, desc: i.desc })) }) };
if (String(d.decision).toLowerCase() !== 'accept') return { batch: [resp('OPERATOR_REJECTED', 'OPERATOR'), pendingMsg] };
const plc = flow.get('plc') || {};
if (plc.mode !== 'REMOTE_MANUAL' || plc.maintenance === true) {
    return { batch: [resp('REJECTED', plc.maintenance === true ? 'MAINTENANCE' : `MODE_${plc.mode}`), pendingMsg] };
}
const cmd = { topic: job.command_topic, qos: 1, retain: false, payload: JSON.stringify({ job_order_id: job.job_order_id,
    code: job.code, value: job.value, expires_at: Math.floor(now) + 30, operator_accepted: 1, job_hash: job.job_hash }) };
return { batch: [resp('OPERATOR_ACCEPTED', 'OPERATOR'), cmd, pendingMsg] };

// 운전원 대기 60초(벽시계, 17번 E18): 넘으면 OPERATOR_TIMEOUT 으로 거부하고 대기 목록에서 뺀다.
const reg = global.get('registry');
const pending = flow.get('pending') || {};
const now = Date.now() / 1000;
const iso = new Date().toISOString();
const out = [];
for (const [id, job] of Object.entries(pending)) {
    if (now - job.received_at >= 60) {
        delete pending[id];
        out.push({ topic: `${reg.request.response_prefix}/${id}`, qos: 1, retain: false,
            payload: JSON.stringify({ job_order_id: id, stage: 'operator', status: 'REJECTED', reason: 'OPERATOR_TIMEOUT', ts: iso }) });
    }
}
const items = Object.values(pending).sort((a, b) => a.received_at - b.received_at);
const h = items[0];
const snapshot = JSON.stringify({ count: items.length, head_job: h ? h.job_order_id : '', head_wm: h ? h.work_master_id : '',
    head_desc: h ? h.desc : '대기 중인 요청 없음', head_context: h ? (h.context_summary || '') : '',
    items: items.map(i => ({ job_order_id: i.job_order_id, work_master_id: i.work_master_id, desc: i.desc })) });
// 목록이 바뀌었거나 대기 중이면(대기 시간 표시) 다시 낸다
if (out.length || items.length || context.get('last') !== snapshot) {
    const payload = JSON.parse(snapshot);
    payload.head_wait_s = h ? Math.round(now - h.received_at) : 0;
    out.push({ topic: reg.request.pending_topic, qos: 1, retain: true, payload: JSON.stringify(payload) });
    context.set('last', snapshot);
}
flow.set('pending', pending);
return out.length ? { batch: out } : null;

// PLC 의 외부 요청 ACK(엣지가 PLC 레지스터에서 읽어 …/ack/request 로 낸 것)를 요청 응답(셋째 단계 plc)으로 올린다.
const reg = global.get('registry');
let a;
try { a = JSON.parse(msg.payload); } catch (e) { return null; }
if (!a.job_order_id) return null;
return { batch: [{ topic: `${reg.request.response_prefix}/${a.job_order_id}`, qos: 1, retain: false,
    payload: JSON.stringify({ job_order_id: a.job_order_id, stage: 'plc', status: a.code === 0 ? 'ACCEPTED' : 'REJECTED',
        reason: a.result, plc_ack_code: a.code, ts: new Date().toISOString() }) }] };
